/// packs many independently governed rules into one list. [`evaluate_overlay`]'s generic per-leaf repair treats a
/// refused leaf as one opaque value and substitutes the *entire* kernel value for it — correct for a scalar (a
/// sensitivity class, a role list) but wrong here: one widened or removed kernel-owned rule would discard every rule
/// the project narrowed, added or the OS derived from its native layout elsewhere in the same list, and — once the
/// kernel baseline is the currently installed template rather than a stale pre-update commit (repair-2 iteration-2
/// finding) — the kernel array no longer even shares the project array's shape (native-layout rules sit ahead of the
/// template's own rules), so a whole-array substitution silently corrupts the document instead of repairing it.
///
/// This evaluates every rule in `new_value` against its kernel counterpart by pattern and repairs only what needs
/// it: a widened or removed kernel-owned rule is replaced, in place, by the kernel's own rule (or appended, when
/// missing entirely — last-match-wins, so a restored floor rule takes final say); a compliant narrowing, an
/// untouched kernel rule and a project-declared rule (no matching kernel pattern — OC-P2-04, honoured as a
/// declaration) all pass through unchanged. Returns the effective (repaired) array plus one applied/refused record
/// per rule that needed one, keyed `paths` throughout (like every other overlay key) so `gov policy overrides` and
/// doctor D027 read it the same way.
///
/// **AR68-F3.** "No matching kernel pattern" means no kernel rule with the *identical* pattern string — it does
/// not mean the rule's domain is unclaimed. `paths::decide` is last-match-wins, so a project pattern appended
/// after a kernel rule it merely *overlaps* (`archive/*.txt` appended after the kernel's own `archive/**`) still
/// decides the paths the two share, exactly as if the patterns had matched exactly. A rule with no exact kernel
/// counterpart is therefore also checked against every kernel rule whose domain it overlaps
/// ([`patterns_may_overlap`]) and must decide no less restrictively than each of them
/// ([`overlap_is_no_less_restrictive`] — by actual decided output, not by requiring the same `class` label a
/// widened exact match must keep); one that fails is refused, reported and dropped (never added to `effective`)
/// exactly like a widened exact match, while a genuine narrowing or a declaration that overlaps no kernel rule
/// at all is honoured, per OC-P2-04.
pub fn evaluate_path_rules_overlay(
    kernel_value: Option<&Value>,
    new_value: &Value,
    label: &str,
    source: &str,
) -> OverlayVerdict {
    let mut out = OverlayVerdict::default();
    let entry = |value: &Value, kernel_value: &Value, reason: &str| {
        json!({"policy": label, "key": "paths", "value": value, "source": source,
            "kernel_value": kernel_value, "reason": reason})
    };
    let Some(kernel) = kernel_value.and_then(|v| v.as_array()) else {
        out.effective = new_value.clone();
        out.refused.push(entry(
            new_value,
            &Value::Null,
            "REPOSITORY_CONTRACT.paths has no kernel template baseline (fail closed)",
        ));
        return out;
    };
    let Some(new_arr) = new_value.as_array() else {
        out.effective = kernel_value.cloned().unwrap_or(json!([]));
        out.refused.push(entry(
            new_value,
            kernel_value.unwrap(),
            "REPOSITORY_CONTRACT.paths must stay a list",
        ));
        return out;
    };
    let mut seen_kernel = vec![false; kernel.len()];
    let mut effective: Vec<Value> = Vec::with_capacity(new_arr.len());
    for nr in new_arr {
        let np = nr.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
        let nobj = nr.as_object();
        if np.is_empty() || nobj.is_none() {
            out.refused.push(entry(
                nr,
                &Value::Null,
                "every path rule needs a non-empty pattern and must be an object",
            ));
            continue; // malformed: dropped from the effective document (fail closed for this one rule)
        }
        match kernel
            .iter()
            .enumerate()
            .find(|(_, kr)| kr.get("pattern").and_then(|v| v.as_str()) == Some(np))
        {
            Some((ki, krule)) => {
                seen_kernel[ki] = true;
                let kobj = krule.as_object().cloned().unwrap_or_default();
                match path_rule_narrowing(&kobj, nobj.unwrap()) {
                    Ok(()) => {
                        if nr != krule {
                            out.applied.push(json!({"policy": label, "key": "paths", "value": nr,
                                "source": source, "mode": "path_rules", "kernel_value": krule}));
                        }
                        effective.push(nr.clone());
                    }
                    Err(reason) => {
                        out.refused.push(entry(
                            nr,
                            krule,
                            &format!(
                                "REPOSITORY_CONTRACT.paths[{np}]: {reason} (POLICY_PRECEDENCE mode 'path_rules', rule REPOSITORY_CONTRACT.paths)"
                            ),
                        ));
                        effective.push(krule.clone());
                    }
                }
            }
            None => {
                // AR68-F3 / OC-P2-04: no kernel rule shares this exact pattern, but `paths::decide` is
                // last-match-wins, so an appended pattern can still decide paths a kernel rule already governs
                // whenever the two patterns' domains overlap (`archive/*.txt` appended after the kernel's own
                // `archive/**`, for example) — refused, reported and left without effect exactly like a
                // widened exact-pattern match, unless it is at least as restrictive as every kernel rule it
                // overlaps (a genuine narrowing) or overlaps no kernel rule at all (a plain declaration), either
                // of which OC-P2-04 requires to still be honoured. `secret` kernel rules are excluded from the
                // scan: `RepositoryContract::decide`'s own `secret_locked` latch already keeps a later
                // non-secret rule from un-classifying a path a secret rule matched, independent of list order,
                // so checking here would only produce false refusals (an ordinary native-layout declaration
                // that happens to contain a `.env` or `secrets/` path somewhere inside it).
                let widened = kernel.iter().find_map(|krule| {
                    if krule.get("class").and_then(|v| v.as_str()) == Some(crate::paths::SECRET_CLASS) {
                        return None;
                    }
                    let kp = krule.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
                    if kp.is_empty() || !patterns_may_overlap(np, kp) {
                        return None;
                    }
                    overlap_is_no_less_restrictive(krule, nr)
                        .err()
                        .map(|reason| (krule, kp, reason))
                });
                match widened {
                    Some((krule, kp, reason)) => {
                        out.refused.push(entry(
                            nr,
                            krule,
                            &format!(
                                "REPOSITORY_CONTRACT.paths[{np}]: {reason}; '{np}' overlaps kernel rule '{kp}', and REPOSITORY_CONTRACT.paths is last-match-wins, so appending this pattern would widen authority for the paths the two share (POLICY_PRECEDENCE mode 'path_rules', rule REPOSITORY_CONTRACT.paths)"
                            ),
                        ));
                        // left without effect: the widening rule is dropped from `effective`. The kernel rule
                        // it would have shadowed is either already kept elsewhere in `new_arr` at its own
                        // (earlier) position, or restored below (kernel rules may not be removed) — either way
                        // it continues to decide the paths the two rules share.
                    }
                    // OC-P2-04: no kernel floor governs this pattern, or this pattern is at least as
                    // restrictive as every kernel rule it overlaps: the project's own declaration is honoured.
                    None => effective.push(nr.clone()),
                }
            }
        }
    }
    for (ki, krule) in kernel.iter().enumerate() {
        if !seen_kernel[ki] {
            let kp = krule.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
            out.refused.push(entry(
                &Value::Null,
                krule,
                &format!(
                    "REPOSITORY_CONTRACT.paths: kernel path rule '{kp}' is missing (kernel path rules may not be removed) (POLICY_PRECEDENCE mode 'path_rules', rule REPOSITORY_CONTRACT.paths)"
                ),
            ));
            effective.push(krule.clone()); // restored last, so it wins any pattern match over what precedes it
        }
    }
    out.effective = json!(effective);
    out
}

/// **AR84-C2 (Property C).** Before P2-AR-0084, `cit/mod.rs::apply_op`'s `reclassify_adoption_floor` validated only
/// that every proposed rule carried a string `pattern` and `class`, then wrote them straight into the project
/// adoption floor — which `PolicySet::load` then unions ONTO the front of the immutable kernel template's own
/// `paths` array (`[floor rules ..., kernel template rules ...]`, native-layout rules ahead of the template's own).
/// `evaluate_path_rules_overlay` (the live overlay's own widening check) matches a project rule to the kernel
/// rule with the SAME pattern, or — when none matches exactly — to every kernel rule it merely OVERLAPS
/// ([`patterns_may_overlap`]), refusing a widening either way. The governed reclassification route never ran that
/// same check on what it was about to write: a floor rule DUPLICATING a kernel-TEMPLATE pattern with a weaker class
/// was written, unioned in ahead of the template's own rule, and — `RepositoryContract::decide` being last-match-
/// wins — never even reached the template rule it should have been compared against.
///
/// This is the one gate: every proposed floor rule is checked against every kernel-template rule it overlaps, using
/// EXACTLY [`overlap_is_no_less_restrictive`] — the same comparison the live overlay already trusts, not a second,
/// parallel one this function invents. A `secret`-class kernel rule is excluded from the scan for the identical
/// reason [`evaluate_path_rules_overlay`] excludes it (`RepositoryContract::decide`'s own `secret_locked` latch
/// already protects it independently of list order).
///
/// Partitions rather than fails the whole proposal: an ordinary reclassification legitimately mixes several rules
/// (narrowings, additions, native-layout updates), and one bad rule must not block every other one — exactly how
/// [`evaluate_path_rules_overlay`] treats the live overlay document rule by rule. Returns `(accepted, refused)`;
/// `refused` pairs each dropped rule with the kernel pattern it overlaps and why — the caller
/// (`cit::mod::apply_op`) writes only `accepted` into the floor and must not silently drop `refused` (OC-P2-04 §4).
pub fn partition_floor_rules_against_kernel(
    kernel_paths: &[Value],
    proposed_rules: &[Value],
) -> (Vec<Value>, Vec<Value>) {
    let mut accepted = vec![];
    let mut refused = vec![];
    for nr in proposed_rules {
        let np = nr.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
        let mut violation: Option<(String, String)> = None;
        if np.is_empty() {
            violation = Some(("<none>".into(), "every proposed floor rule needs a non-empty pattern".into()));
        } else {
            for krule in kernel_paths {
                if krule.get("class").and_then(|v| v.as_str()) == Some(crate::paths::SECRET_CLASS) {
                    continue;
                }
                let kp = krule.get("pattern").and_then(|v| v.as_str()).unwrap_or("");
                if kp.is_empty() || !patterns_may_overlap(np, kp) {
                    continue;
                }
                if let Err(reason) = overlap_is_no_less_restrictive(krule, nr) {
                    violation = Some((kp.to_string(), reason));
                    break;
                }
            }
        }
        match violation {
            None => accepted.push(nr.clone()),
            Some((kp, reason)) => refused.push(json!({
                "rule": nr, "overlaps_kernel_pattern": kp,
                "reason": format!(
                    "{reason}; the adoption floor is unioned onto the kernel template's own paths and must never \
                     weaken it (OD-P2-08 §4, AR84-C2) -- this rule was dropped and never written"
                ),
            })),
        }
    }
    (accepted, refused)
}

